/* One displayed decision context and one immutable evidence snapshot for every shortlist entry. */
(function(global){
 'use strict';
 let display=null;
 const clone=value=>structuredClone(value),key=()=>criteriaContextKey();
 function criteria(){if(Y.route==='place'&&display?.key===key()&&display.areaId===Y.selected)return display.criteria;return ['criteria','market','strategy'].includes(Y.route)?draft:Y.criteria;}
 function setDisplayContext(areaId,value=criteria(),origin=Y.route){if(!AREA_INDEX.has(areaId))return false;display={areaId,key:key(),criteria:clone(value),origin};return true;}
 function clearDisplayContext(){display=null;}
 function displayBanner(){const c=criteria(),privateView=diffCriteria(Y.criteria,c).length>0;if(Y.route!=='place'||!privateView)return '';return `<p class="strategy-map-reading" role="status"><strong>${tr('กำลังดูเกณฑ์แบบร่างที่เลือกมา','Showing the draft you opened')}</strong> · ${tr('เกณฑ์ทีมยังไม่เปลี่ยน การเล็งทำเลจะเก็บแบบร่างนี้','Team criteria are unchanged. Shortlisting captures this draft.')} <button type="button" class="quiet-link" data-decision-team-view>${tr('ดูด้วยเกณฑ์ทีม','Use team criteria')}</button></p>`;}
 function canonical(value){if(value===null||typeof value==='boolean'||typeof value==='string')return JSON.stringify(value);if(typeof value==='number'){if(!Number.isFinite(value))throw new TypeError('Non-finite decision evidence');return JSON.stringify(value);}if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';if(value&&typeof value==='object')return '{'+Object.keys(value).filter(k=>value[k]!==undefined).sort().map(k=>JSON.stringify(k)+':'+canonical(value[k])).join(',')+'}';throw new TypeError('Unsupported decision evidence');}
 const utf8=value=>{const encoded=unescape(encodeURIComponent(value)),bytes=new Uint8Array(encoded.length);for(let i=0;i<encoded.length;i++)bytes[i]=encoded.charCodeAt(i);return bytes;};
 async function digest(value){const provider=global.crypto?.subtle||globalThis.crypto?.subtle;if(!provider)throw new Error('Secure hashing is unavailable');const bytes=await provider.digest('SHA-256',utf8(value));return Array.from(new Uint8Array(bytes),n=>n.toString(16).padStart(2,'0')).join('');}
 function freeze(value){if(value&&typeof value==='object'&&!Object.isFrozen(value)){Object.values(value).forEach(freeze);Object.freeze(value);}return value;}
 function dependencies(industry){return ['area-context',industry+'-supply','industry-profiles','brand-presets','brand-strategy-profiles',...(industry==='nonbank'?['nonbank-company-scopes','nonbank-assignment-bounds']:[])];}
 function manifest(industry){const m=global.YOLK_RUNTIME?.evaluationManifest,release=global.YOLK_RUNTIME?.release||global.document?.querySelector?.('meta[name="yolk-release"]')?.content;if(!m||m.schemaVersion!=='yolk.evaluation-manifest/1.0'||!m.app?.release||release&&m.app.release!==release)throw new Error('Decision evidence manifest is unavailable or belongs to another release');const records=dependencies(industry).map(id=>{const matches=(m.dependencies||[]).filter(x=>x.id===id);if(matches.length!==1||!/^([a-f0-9]{64})$/.test(matches[0].sha256)||!matches[0].file||!Number.isSafeInteger(matches[0].bytes)||matches[0].bytes<0)throw new Error('Decision source dependency unavailable: '+id);return clone(matches[0]);});if(!Array.isArray(m.app.runtimeFiles)||!m.app.runtimeFiles.length||m.app.runtimeFiles.some(x=>!x.file||!/^([a-f0-9]{64})$/.test(x.sha256)))throw new Error('Decision engine binding unavailable');return {schemaVersion:m.schemaVersion,app:clone(m.app),dependencies:records};}
 async function capture(areaId,options={}){const c=clone(options.criteria||criteria()),contextKey=key(),actorId=Y.actor,industry=Y.industry,origin=options.origin||Y.route,route=Y.route,revision=global.YOLK_RUNTIME?.revision;if(criteriaErrors(c).length)throw new Error('Resolve invalid draft criteria before shortlisting');const base=global.YolkStrategyUI?.snapshot(areaId,{criteria:c});if(!base)throw new Error('Location evidence is unavailable');const sourceManifest=manifest(industry);const criteriaCanonical=canonical(c);const [criteriaHash,manifestHash]=await Promise.all([digest(criteriaCanonical),digest(canonical(sourceManifest))]);const stillCurrent=()=>contextKey===key()&&actorId===Y.actor&&route===Y.route&&revision===global.YOLK_RUNTIME?.revision&&(canonical(options.criteria||criteria())===criteriaCanonical);if(!stillCurrent())throw new Error('The decision context changed while saving');const result={...clone(base),snapshotSchemaVersion:'yolk.decision-snapshot/1.0',criteria:c,criteriaHash,criteriaHashAlgorithm:'SHA-256 of canonical JSON with lexicographically sorted object keys; array order retained',sourceManifest,sourceManifestHash:manifestHash,origin,actorId,capturedContextKey:contextKey};result.evidenceHash=await digest(canonical(result));if(!stillCurrent())throw new Error('The decision context changed while saving');return freeze(result);}
 global.document?.addEventListener?.('click',event=>{if(!event.target.closest?.('[data-decision-team-view]'))return;clearDisplayContext();render();});
 global.YolkDecisionSnapshot=Object.freeze({displayCriteria:criteria,setDisplayContext,clearDisplayContext,displayBanner,capture,canonical,digest,dependencies});
})(window);
